#include <iostream>
#include <cmath>
#include <iomanip>

double roundToDecimals(double val, int decimals) {
    double factor = std::pow(10.0, decimals);
    return std::floor(val * factor + 0.5) / factor;
}

int reverseInteger(int n) {
    int rev = 0;
    while (n > 0) {
        rev = rev * 10 + (n % 10);
        n /= 10;
    }
    return rev;
}

void printDigitsSpaced(int n) {
    if (n < 10) {
        std::cout << n;
        return;
    }
    printDigitsSpaced(n / 10);
    std::cout << "  " << (n % 10);
}

int main() {
    double val = 45.6789;
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "Original: " << val << "\n";
    std::cout << "Nearest integer: " << std::setprecision(0) << roundToDecimals(val, 0) << "\n";
    std::cout << "Tenths: " << std::setprecision(1) << roundToDecimals(val, 1) << "\n";
    std::cout << "Hundredths: " << std::setprecision(2) << roundToDecimals(val, 2) << "\n";

    int number = 4562;
    std::cout << "Digits spaced: ";
    printDigitsSpaced(number);
    std::cout << "\nReversed: " << reverseInteger(number) << "\n";
    return 0;
}

#include <iostream>

long long powerRecursive(long long base, int exponent) {
    if (exponent <= 1) {
        return base;
    }
    return base * powerRecursive(base, exponent - 1);
}

void solveHanoi(int n, int fromPeg, int toPeg, int tempPeg) {
    if (n == 1) {
        std::cout << fromPeg << " -> " << toPeg << "\n";
        return;
    }
    solveHanoi(n - 1, fromPeg, tempPeg, toPeg);
    std::cout << fromPeg << " -> " << toPeg << "\n";
    solveHanoi(n - 1, tempPeg, toPeg, fromPeg);
}

int main() {
    long long p = powerRecursive(3, 4);
    std::cout << "3^4 = " << p << "\n";
    std::cout << "Towers of Hanoi (3 disks):\n";
    solveHanoi(3, 1, 3, 2);
    return 0;
}
